from pathlib import Path
import html
base=Path('/mnt/data/v2work/frontend/assets/visuals')
base.mkdir(parents=True,exist_ok=True)

def svg(name, title, body):
    s=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 160">
<rect width="260" height="160" fill="white"/><text x="130" y="18" text-anchor="middle" font-family="Arial" font-size="13" font-weight="bold">{html.escape(title)}</text>{body}
</svg>'''
    (base/name).write_text(s,encoding='utf-8')

